def lexicographically_smallest_rotation(lst):
    n = len(lst)
    if n == 0:
        return []
    best = lst[:]
    for k in range(1, n):
        cand = lst[k:] + lst[:k]
        if cand < best:
            best = cand
    return best

def are_all_rotations_equal(lst):
    n = len(lst)
    if n <= 1:
        return True
    return all(x == lst[0] for x in lst)

def min_left_rotations_to_sort(lst):
    n = len(lst)
    if n <= 1:
        return 0
    target = sorted(lst)
    for k in range(n):
        if lst[k:] + lst[:k] == target:
            return k
    return -1

def count_distinct_rotations(lst):
    n = len(lst)
    if n == 0:
        return 1
    seen = set()
    for k in range(n):
        seen.add(tuple(lst[k:] + lst[:k]))
    return len(seen)

def moving_average_round_int(lst, k):
    n = len(lst)
    if k <= 0 or k > n:
        return []
    res = []
    for i in range(n - k + 1):
        window = lst[i:i + k]
        res.append(round(sum(window) / k))
    return res

def moving_average_2dp(lst, k):
    n = len(lst)
    if k <= 0 or k > n:
        return []
    res = []
    for i in range(n - k + 1):
        window = lst[i:i + k]
        res.append(round(sum(window) / k, 2))
    return res

def moving_average_floor(lst, k):
    n = len(lst)
    if k <= 0 or k > n:
        return []
    res = []
    for i in range(n - k + 1):
        window = lst[i:i + k]
        res.append(sum(window) // k)
    return res

def remove_every_kth_1indexed(lst, k):
    if k <= 0:
        return lst[:]
    return [x for idx, x in enumerate(lst, start=1) if idx % k != 0]

def remove_every_kth_0indexed(lst, k):
    if k <= 0:
        return lst[:]
    return [x for idx, x in enumerate(lst) if idx % k != 0]

def keep_every_kth(lst, k):
    if k <= 0:
        return []
    return [x for idx, x in enumerate(lst, start=1) if idx % k == 0]

def remove_every_kth_starting_at(lst, k, start):
    if k <= 0:
        return lst[:]
    remove_set = set(range(start, len(lst), k))
    return [x for idx, x in enumerate(lst) if idx not in remove_set]

def rle_encode(lst):
    res = []
    for x in lst:
        if res and res[-1][0] == x:
            res[-1][1] += 1
        else:
            res.append([x, 1])
    return res

def rle_decode(pairs):
    res = []
    for value, count in pairs:
        res.extend([value] * count)
    return res

def rle_num_groups(lst):
    if not lst:
        return 0
    count = 1
    for i in range(1, len(lst)):
        if lst[i] != lst[i - 1]:
            count += 1
    return count

def rle_longest_run_value(lst):
    if not lst:
        return None
    best_val = lst[0]
    best_len = 1
    cur_val = lst[0]
    cur_len = 1
    for i in range(1, len(lst)):
        if lst[i] == cur_val:
            cur_len += 1
        else:
            cur_val = lst[i]
            cur_len = 1
        if cur_len > best_len:
            best_len = cur_len
            best_val = cur_val
    return best_val

def most_frequent_value(lst):
    if not lst:
        return None
    counts = {}
    for x in lst:
        counts[x] = counts.get(x, 0) + 1
    best = None
    best_count = -1
    for x in lst:
        if counts[x] > best_count:
            best_count = counts[x]
            best = x
    return best

def collapse_consecutive_duplicates(lst):
    res = []
    for x in lst:
        if not res or res[-1] != x:
            res.append(x)
    return res

def second_largest_distinct(lst):
    distinct = sorted(set(lst), reverse=True)
    if len(distinct) < 2:
        return None
    return distinct[1]
